"""Settings, provider, credential, routing and runtime-facts HTTP surface."""

from __future__ import annotations

import shutil
import stat
import time
from pathlib import Path
from typing import Any, Literal, cast

from fastapi import APIRouter, HTTPException, Query, Request, status
from pydantic import BaseModel, ConfigDict, Field

import docker
from codepilot import __version__
from codepilot.api.routes import ApiContext
from codepilot.config import PROJECT_ROOT
from codepilot.settings.catalog import template
from codepilot.settings.models import (
    CredentialRef,
    ModelConfig,
    ProviderConfig,
    SettingsDocument,
)
from codepilot.settings.service import SettingsService
from codepilot.settings.store import VersionConflictError

__all__ = ["build_settings_router"]


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)


class SectionUpdate(_StrictModel):
    version: int = Field(ge=0)
    values: dict[str, Any]


class ProviderCreate(_StrictModel):
    version: int = Field(ge=0)
    provider: ProviderConfig


class ProviderUpdate(_StrictModel):
    version: int = Field(ge=0)
    provider: ProviderConfig


class TemplateCreate(_StrictModel):
    version: int = Field(ge=0)
    catalog_id: str
    provider_id: str
    name: str | None = None
    base_url: str | None = None
    region: str | None = None
    api_key_env: str | None = None


class CredentialUpdate(_StrictModel):
    version: int = Field(ge=0)
    mode: Literal["value", "env"]
    value: str | None = Field(default=None, max_length=8192)
    env_name: str | None = Field(default=None, max_length=64)


class ModelUpsert(_StrictModel):
    version: int = Field(ge=0)
    original_model_id: str | None = None
    model: ModelConfig


class ConnectionTest(_StrictModel):
    kind: Literal["config", "models", "inference"] = "config"
    model_id: str | None = None
    confirm_cost: bool = False


class ImportRequest(_StrictModel):
    version: int = Field(ge=0)
    payload: dict[str, Any]


class CleanupRequest(_StrictModel):
    version: int = Field(ge=0)
    task_ids: list[str] = Field(min_length=1, max_length=50)
    confirmation: str


def _context(request: Request) -> ApiContext:
    return cast(ApiContext, request.app.state.api_context)


def _service(context: ApiContext) -> SettingsService:
    return context.settings_service


def _document_view(service: SettingsService, document: SettingsDocument) -> dict[str, Any]:
    return {
        **document.describe(),
        "secure_storage_available": service.vault.available,
        "providers": [service.provider_view(item) for item in document.providers.values()],
    }


def _git_commit() -> str | None:
    head = PROJECT_ROOT / ".git" / "HEAD"
    try:
        raw = head.read_text(encoding="utf-8").strip()
    except OSError:
        return None
    if raw.startswith("ref:"):
        ref = PROJECT_ROOT / ".git" / raw.partition(" ")[2].strip()
        try:
            return ref.read_text(encoding="utf-8").strip()[:12]
        except OSError:
            return None
    return raw[:12] or None


def _directory_size(path: Path, *, limit: int = 200_000) -> tuple[int, int]:
    total = 0
    files = 0
    if not path.exists():
        return 0, 0
    for item in path.rglob("*"):
        if files >= limit:
            break
        if item.is_file():
            try:
                total += item.stat().st_size
                files += 1
            except OSError:
                continue
    return total, files


def _docker_status() -> dict[str, Any]:
    started = time.monotonic()
    try:
        client = docker.from_env(timeout=2)
        try:
            client.ping()
            version = client.version()
        finally:
            client.close()
        return {
            "available": True,
            "server_version": version.get("Version") if isinstance(version, dict) else None,
            "latency_ms": int((time.monotonic() - started) * 1000),
            "error": None,
        }
    except Exception as exc:  # pragma: no cover - daemon availability varies
        return {
            "available": False,
            "server_version": None,
            "latency_ms": int((time.monotonic() - started) * 1000),
            "error": f"{type(exc).__name__}: {str(exc)[:200]}",
        }


def _force_rmtree(path: Path, *, attempts: int = 5) -> None:
    def onerror(func: Any, target: str, _exc: Any) -> None:
        try:
            Path(target).chmod(stat.S_IWRITE | stat.S_IREAD)
            func(target)
        except OSError:
            pass

    # Windows anti-virus scanners hold freshly written files (git objects,
    # sqlite journals) without FILE_SHARE_DELETE for a few milliseconds, so
    # unlink/rmdir intermittently fail with sharing violations. Retry with
    # exponential backoff instead of turning a transient scan into an
    # ``artifact_cleanup_failed`` skip on the cleanup route.
    delay = 0.1
    for attempt in range(attempts):
        shutil.rmtree(path, onerror=onerror)
        if not path.exists():
            return
        if attempt == attempts - 1:
            break
        time.sleep(delay)
        delay *= 2.0
    survivors = sorted(str(item.relative_to(path)) for item in path.rglob("*"))[:20]
    raise OSError(
        f"artifact directory could not be fully removed: {path.name}; survivors={survivors}"
    )


def build_settings_router() -> APIRouter:
    router = APIRouter(prefix="/api/v1")

    @router.get("/settings")
    def read_settings(request: Request) -> dict[str, Any]:
        context = _context(request)
        service = _service(context)
        return _document_view(service, service.document())

    @router.put("/settings/sections/{section}")
    def update_section(request: Request, section: str, body: SectionUpdate) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.update_section(section, body.values, expected_version=body.version)
        return _document_view(service, document)

    @router.get("/settings/catalog")
    def read_catalog(request: Request) -> list[dict[str, Any]]:
        return _service(_context(request)).catalog()

    @router.get("/settings/providers")
    def read_providers(request: Request) -> list[dict[str, Any]]:
        return _service(_context(request)).providers_view()

    @router.post("/settings/providers", status_code=status.HTTP_201_CREATED)
    def create_provider(request: Request, body: ProviderCreate) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.create_provider(body.provider, expected_version=body.version)
        return _document_view(service, document)

    @router.post("/settings/providers/from-template", status_code=status.HTTP_201_CREATED)
    def create_from_template(request: Request, body: TemplateCreate) -> dict[str, Any]:
        service = _service(_context(request))
        try:
            item = template(body.catalog_id)
        except KeyError as exc:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail={"code": "catalog_not_found", "message": str(exc)},
            ) from exc
        provider = ProviderConfig(
            provider_id=body.provider_id,
            name=body.name or item.name,
            protocol=item.protocol,
            base_url=body.base_url or item.base_url,
            catalog_id=item.catalog_id,
            custom=item.catalog_id == "custom",
            region=body.region,
            models=item.models,
            credential=CredentialRef(kind="env", name=body.api_key_env or item.api_key_env)
            if (body.api_key_env or item.api_key_env)
            else CredentialRef(),
        )
        document = service.create_provider(provider, expected_version=body.version)
        return _document_view(service, document)

    @router.put("/settings/providers/{provider_id}")
    def update_provider(request: Request, provider_id: str, body: ProviderUpdate) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.update_provider(
            provider_id, body.provider, expected_version=body.version
        )
        return _document_view(service, document)

    @router.delete("/settings/providers/{provider_id}")
    def delete_provider(
        request: Request,
        provider_id: str,
        version: int = Query(ge=0),
    ) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.delete_provider(provider_id, expected_version=version)
        return _document_view(service, document)

    @router.post("/settings/providers/{provider_id}/credential")
    def set_credential(
        request: Request, provider_id: str, body: CredentialUpdate
    ) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.set_credential(
            provider_id,
            mode=body.mode,
            value=body.value,
            env_name=body.env_name,
            expected_version=body.version,
        )
        return _document_view(service, document)

    @router.delete("/settings/providers/{provider_id}/credential")
    def delete_credential(
        request: Request,
        provider_id: str,
        version: int = Query(ge=0),
    ) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.delete_credential(provider_id, expected_version=version)
        return _document_view(service, document)

    @router.post("/settings/providers/{provider_id}/models", status_code=status.HTTP_201_CREATED)
    def upsert_model(request: Request, provider_id: str, body: ModelUpsert) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.upsert_model(
            provider_id,
            body.model,
            original_model_id=body.original_model_id,
            expected_version=body.version,
        )
        return _document_view(service, document)

    @router.put("/settings/providers/{provider_id}/models/{model_id:path}")
    def update_model(
        request: Request,
        provider_id: str,
        model_id: str,
        body: ModelUpsert,
    ) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.upsert_model(
            provider_id,
            body.model,
            original_model_id=model_id,
            expected_version=body.version,
        )
        return _document_view(service, document)

    @router.delete("/settings/providers/{provider_id}/models/{model_id:path}")
    def delete_model(
        request: Request,
        provider_id: str,
        model_id: str,
        version: int = Query(ge=0),
    ) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.delete_model(provider_id, model_id, expected_version=version)
        return _document_view(service, document)

    @router.get("/settings/models")
    def available_models(request: Request) -> list[dict[str, Any]]:
        return _service(_context(request)).available_models()

    @router.post("/settings/providers/{provider_id}/test")
    def test_provider(request: Request, provider_id: str, body: ConnectionTest) -> dict[str, Any]:
        service = _service(_context(request))
        return service.test_connection(
            provider_id,
            kind=body.kind,
            model_id=body.model_id,
            confirm_cost=body.confirm_cost,
        )

    @router.post("/settings/providers/{provider_id}/discover")
    def discover_models(request: Request, provider_id: str) -> dict[str, Any]:
        service = _service(_context(request))
        return service.discover_models(provider_id)

    @router.get("/settings/export")
    def export_settings(request: Request) -> dict[str, Any]:
        return _service(_context(request)).export_config()

    @router.post("/settings/import")
    def import_settings(request: Request, body: ImportRequest) -> dict[str, Any]:
        service = _service(_context(request))
        document = service.import_config(body.payload, expected_version=body.version)
        return _document_view(service, document)

    @router.get("/settings/audit")
    def audit(
        request: Request, limit: int = Query(default=40, ge=1, le=200)
    ) -> list[dict[str, Any]]:
        return _service(_context(request)).store.audit(limit=limit)

    @router.get("/settings/logs")
    def logs(
        request: Request, limit: int = Query(default=80, ge=1, le=500)
    ) -> list[dict[str, Any]]:
        context = _context(request)
        items = context.database.recent_events(limit=limit)
        result: list[dict[str, Any]] = []
        for item in items:
            result.append(
                {
                    "seq": item.get("seq"),
                    "run_id": item.get("run_id"),
                    "type": context.content_scrubber.text(str(item.get("type") or "")),
                    "node": context.content_scrubber.text(str(item.get("node") or "")),
                    "status": context.content_scrubber.text(str(item.get("status") or "")),
                    "summary": context.content_scrubber.text(str(item.get("summary") or "")),
                    "error": context.content_scrubber.text(str(item.get("error") or "")),
                    "timestamp": item.get("timestamp"),
                }
            )
        return result

    @router.get("/settings/docs/{name:path}")
    def documentation(request: Request, name: str) -> dict[str, str]:
        context = _context(request)
        allowed = {
            "README.md": context.settings.readme_path,
            "architecture": context.settings.docs_dir / "02-实现方案.md",
            "agents": context.settings.docs_dir / "03-AGENTS.md",
            "security": context.settings.docs_dir / "06-security.md",
        }
        path = allowed.get(name)
        if path is None or not path.is_file():
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND,
                detail={"code": "document_not_found", "message": "documentation not found"},
            )
        return {"name": name, "content": path.read_text(encoding="utf-8")[:400_000]}

    @router.get("/settings/runtime")
    def runtime_facts(request: Request) -> dict[str, Any]:
        context = _context(request)
        service = _service(context)
        document = service.document()
        stats = context.database.queue_stats()
        run_dir = context.settings.runs_dir()
        artifact_bytes, artifact_files = _directory_size(run_dir)
        return {
            "product": "CodePilot-Repair",
            "version": __version__,
            "git_commit": _git_commit(),
            "python": None,
            "worker": {
                **stats,
                "lease_seconds": context.settings.api_worker_lease_seconds,
                "poll_seconds": context.settings.api_worker_poll_seconds,
                "execution_backend": context.settings.api_execution_backend,
            },
            "docker": _docker_status(),
            "event_sink": {
                "kind": "sqlite-archive",
                "path": "artifacts/api/api.sqlite3",
                "status": "available",
            },
            "checkpointer": {
                "kind": "langgraph-sqlite",
                "scope": "per-run artifacts/<run_id>/checkpoints.sqlite",
                "status": "available",
            },
            "storage": {
                "artifact_bytes": artifact_bytes,
                "artifact_files": artifact_files,
                "artifact_root": "artifacts/runs",
            },
            "secure_storage_available": service.vault.available,
            "settings_version": document.version,
            "providers": [service.config_check(provider_id) for provider_id in document.providers],
            "audit": service.store.audit(limit=20),
        }

    @router.post("/settings/cleanup")
    def cleanup(request: Request, body: CleanupRequest) -> dict[str, Any]:
        if body.confirmation != "DELETE":
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail={
                    "code": "confirmation_required",
                    "message": "type DELETE to confirm artifact cleanup",
                },
            )
        context = _context(request)
        current = context.settings_service.document()
        if body.version != current.version:
            raise VersionConflictError(body.version, current.version)
        deleted: list[str] = []
        skipped: list[dict[str, str]] = []
        run_root = context.settings.runs_dir().resolve()
        for task_id in body.task_ids:
            row = context.database.get_by_task(task_id)
            if row is None:
                skipped.append({"task_id": task_id, "reason": "not_found"})
                continue
            target = (context.settings.artifacts_dir / row.artifact_rel).resolve()
            if run_root not in target.parents:
                skipped.append({"task_id": task_id, "reason": "unsafe_artifact_path"})
                continue
            if target.is_dir():
                try:
                    _force_rmtree(target)
                except OSError:
                    skipped.append({"task_id": task_id, "reason": "artifact_cleanup_failed"})
                    continue
            try:
                context.database.delete_finished_task(task_id)
            except KeyError:
                skipped.append({"task_id": task_id, "reason": "not_found"})
                continue
            except ValueError as exc:
                skipped.append({"task_id": task_id, "reason": str(exc)})
                continue
            deleted.append(task_id)
        return {"deleted": deleted, "skipped": skipped, "settings_version": current.version}

    return router

src/codepilot/graph/harness.py:
"""Small lifecycle integration for the existing graph and checkpoint state."""

from __future__ import annotations

import json
from typing import Any

from codepilot.graph.deps import Deps
from codepilot.graph.evidence import failure_summary, verification_view
from codepilot.observability.lifecycle import snapshot_hash
from codepilot.rsi import (
    archive_root,
    load_selection,
    read_json,
    retrieve,
    snapshot_sources,
    version_dir,
)
from codepilot.schemas.state import RepairState


class SnapshotIdentityError(ValueError):
    """A resumed task must never silently switch its fixed policy."""


_SELECTION_ROLES = ("coder", "planner", "reviewer")


def _load_selection_fail_closed(deps: Deps) -> dict[str, Any]:
    """Load the policy selection; a selected candidate must be activatable.

    Phase30 fail-closed gate: when no ``active.json`` pointer exists, the
    builtin defaults apply (code default prompts are allowed only on this
    path). When a pointer exists but the candidate snapshot is unreadable,
    invalid, or missing any of the three role prompts, this raises
    ``SnapshotIdentityError`` naming the candidate, the missing roles and the
    snapshot path — it must never silently fall back to ``deps.*.system_prompt``
    (the v3 defect: a candidate with ``prompts={}`` would have run with code
    defaults while claiming candidate provenance).
    """
    pointer = archive_root() / "active.json"
    if not pointer.exists():
        return {
            "schema_version": 1,
            "version": "builtin-phase26-v1",
            "parent": None,
            "status": "pending",
            "instruction": "",
            "experiences": [],
        }
    try:
        # Pass the root explicitly: load_selection's own default would consult
        # rsi.archive_root(), which is not the harness's (possibly overridden)
        # archive root.
        selection = load_selection(archive_root())
    except (OSError, ValueError, KeyError) as exc:
        deps.lifecycle.emit("policy_load_failed", error=str(exc), fallback="fail_closed")
        raise SnapshotIdentityError(
            f"active candidate selection at {pointer} is unusable ({exc}); "
            "refusing to fall back to builtin defaults"
        ) from exc
    prompts = selection.get("prompts", {})
    missing = [role for role in _SELECTION_ROLES if not prompts.get(role)]
    if missing:
        version = selection.get("version")
        try:
            snapshot_path = version_dir(archive_root(), str(version)) / "snapshot.json"
        except ValueError as exc:
            raise SnapshotIdentityError(
                f"active candidate selection has an invalid version {version!r}: {exc}"
            ) from exc
        raise SnapshotIdentityError(
            f"candidate {version!r} is missing prompts for roles {missing}; "
            f"snapshot: {snapshot_path}; refusing builtin prompt fallback"
        )
    return selection


def begin(state: RepairState, deps: Deps, stage: str) -> RepairState:
    try:
        return _begin(state, deps, stage)
    except SnapshotIdentityError as exc:
        deps.lifecycle.emit("initialization_failed", category="identity", error=str(exc))
        if stage != "finalize":
            raise
        # Finalize must still preserve the original failure, patch and usage.
        return state
    except Exception as exc:
        deps.lifecycle.emit(
            "initialization_failed", category="optional", error=str(exc), fallback="existing_node"
        )
        return state


def _begin(state: RepairState, deps: Deps, stage: str) -> RepairState:
    policy = state.policy_snapshot
    if not deps.harness_started:
        if policy:
            try:
                snapshot = read_json(deps.artifacts.run_dir / "harness/snapshot.json")
            except (OSError, ValueError) as exc:
                raise SnapshotIdentityError(
                    "fixed snapshot unavailable; preserve recovery scene"
                ) from exc
            if snapshot.get("state_schema_version", 1) != 1:
                raise SnapshotIdentityError("snapshot state schema is incompatible")
            if snapshot_hash(snapshot) != policy.get("sha256"):
                raise SnapshotIdentityError(
                    "fixed policy snapshot identity mismatch; refusing in-flight switch"
                )
        else:
            # Phase30: no-pointer -> builtin defaults; pointer present but the
            # candidate cannot deliver role prompts -> SnapshotIdentityError
            # (fail closed, no silent code-prompt fallback).
            selection = _load_selection_fail_closed(deps)
            try:
                sources = snapshot_sources()
            except OSError as exc:
                deps.lifecycle.emit("source_snapshot_unavailable", error=str(exc))
                sources = {}
            snapshot = {
                "selection": selection,
                "selection_source": str(archive_root()),
                "sources": sources,
                "plugins": deps.lifecycle.versions(),
                "configuration": {
                    "environment": deps.env_spec.model_dump(mode="json"),
                    "budget": state.budget.model_dump(mode="json"),
                    "repository": deps.repository,
                    "base_commit": state.base_commit,
                },
                "state_schema_version": 1,
                "prompts": {
                    "coder": selection.get("prompts", {}).get(
                        "coder", getattr(deps.coder, "system_prompt", "")
                    ),
                    "planner": selection.get("prompts", {}).get(
                        "planner", getattr(deps.planner, "system_prompt", "")
                    ),
                    "reviewer": selection.get("prompts", {}).get(
                        "reviewer", getattr(deps.reviewer, "system_prompt", "")
                    ),
                },
            }
            deps.artifacts.write_json("harness/snapshot.json", snapshot)
            policy = {
                "version": selection["version"],
                "sha256": snapshot_hash(snapshot),
                "artifact": "harness/snapshot.json",
                "status": selection.get("status", "pending"),
            }
        selection = snapshot["selection"]
        deps.experience_snapshot = []
        cache = getattr(deps.tools, "query_cache", None)
        if cache is not None:
            counters = state.runtime.get("cache", {})
            cache.hits = int(counters.get("hits", 0))
            cache.misses = int(counters.get("misses", 0))
            if state.events:
                cache.last_invalidation = "worker_restart_no_memory_cache"
        for name, prompt in snapshot.get("prompts", {}).items():
            agent = getattr(deps, name, None)
            if agent is not None and hasattr(agent, "system_prompt"):
                agent.system_prompt = prompt
        deps.coder.experience_feedback = json.dumps(
            {"instruction": selection.get("instruction", ""), "entries": deps.experience_snapshot},
            ensure_ascii=False,
        )
        deps.fixed_selection = selection
        deps.harness_started = True
        deps.lifecycle.bind(
            {"task_id": state.task_id, "stage": stage, "iteration": state.iteration},
            str(policy.get("sha256", "")),
        )
        deps.lifecycle.emit(
            "resume" if state.events else "task_start",
            snapshot=policy,
            reuse="checkpoint-completed nodes, settled responses and identity-valid evidence"
            if state.events
            else "none",
            redo="pending or invalidated stages; no exactly-once guarantee across crash windows"
            if state.events
            else "none",
        )
    if deps.harness_started:
        try:
            audit: list[dict[str, Any]] = []
            deps.experience_snapshot = retrieve(
                deps.fixed_selection,
                deps.repository,
                stage=stage,
                failure_category=state.failure_summary.get("category"),
                environment={
                    "runner": deps.env_spec.test_command,
                    "environment": snapshot_hash(deps.env_spec.model_dump(mode="json")),
                    "version": deps.env_spec.python_version,
                },
                tags=tuple(state.issue_analysis.keywords) if state.issue_analysis else (),
                audit=audit,
            )
            deps.coder.experience_feedback = json.dumps(
                {
                    "instruction": deps.fixed_selection.get("instruction", "")[:1000],
                    "entries": deps.experience_snapshot,
                    "advisory": True,
                },
                ensure_ascii=False,
            )
            deps.lifecycle.emit("experience_selection", decisions=audit)
        except Exception as exc:
            deps.experience_snapshot = []
            deps.coder.experience_feedback = ""
            deps.lifecycle.emit("experience_unavailable", error=str(exc), fallback="no_experience")
    now = deps.clock().isoformat()
    deps.lifecycle.external_wait_seconds = 0.0
    deps.lifecycle.queued_seconds = 0.0
    runtime = {
        **state.runtime,
        "stage": stage,
        "stage_started_at": now,
        "stage_elapsed_seconds": 0.0,
        "activity": "executing",
        "revision": int(state.runtime.get("revision", 0)) + 1,
    }
    deps.lifecycle.bind(
        {
            "task_id": state.task_id,
            "stage": stage,
            "iteration": state.iteration,
            "revision": runtime["revision"],
            "candidate_hash": state.frozen_patch_hash,
        },
        str(policy.get("sha256", "")),
    )
    deps.lifecycle.emit("stage_start", started_at=now, runtime=runtime)
    return state.model_copy(
        update={
            "runtime": runtime,
            "policy_snapshot": policy,
            "experience_refs": [f"{e['id']}@{e['version']}" for e in deps.experience_snapshot],
        }
    )


def complete(
    state: RepairState, update: dict[str, Any], deps: Deps, elapsed: float
) -> dict[str, Any]:
    merged = state.model_copy(update=update)
    runtime = {
        **state.runtime,
        "stage_elapsed_seconds": round(elapsed, 3),
        "activity": "idle",
        "last_completed_at": deps.clock().isoformat(),
    }
    durations = dict(runtime.get("stage_seconds", {}))
    stage = str(runtime.get("stage", "unknown"))
    durations[stage] = round(durations.get(stage, 0) + elapsed, 3)
    runtime["stage_seconds"] = durations
    runtime["external_wait_seconds"] = round(
        float(state.runtime.get("external_wait_seconds", 0)) + deps.lifecycle.external_wait_seconds,
        3,
    )
    runtime["resource_queued_seconds"] = (
        float(state.runtime.get("resource_queued_seconds", 0)) + deps.lifecycle.queued_seconds
    )
    runtime["executing_seconds"] = round(
        float(state.runtime.get("executing_seconds", 0))
        + max(0, elapsed - deps.lifecycle.external_wait_seconds - deps.lifecycle.queued_seconds),
        3,
    )
    cache = getattr(deps.tools, "query_cache", None)
    runtime["has_modification"] = bool(merged.current_patch)
    runtime["event_seq"] = deps.events.last_seq
    runtime["run_id"] = merged.run_id
    runtime["cache"] = {"hits": cache.hits, "misses": cache.misses} if cache else {}
    if merged.current_patch != state.current_patch:
        deps.lifecycle.emit(
            "candidate_changed",
            old=state.frozen_patch_hash,
            new=merged.frozen_patch_hash,
            has_modification=bool(merged.current_patch),
        )
        runtime["last_effective_progress"] = deps.clock().isoformat()
    if stage in {"validate_patch", "run_target_tests", "run_regression"}:
        summary = failure_summary(merged)
        write_projection(deps, f"failures/{stage}-{state.iteration}.json", summary)
        update["failure_summary"] = summary
        deps.lifecycle.emit(
            "after_validation", view=verification_view(merged), failure_summary=summary
        )
        old_evidence = {
            k: v
            for k, v in state.failure_summary.items()
            if k not in {"new_since_last_attempt", "evidence_refs"}
        }
        new_evidence = {
            k: v for k, v in summary.items() if k not in {"new_since_last_attempt", "evidence_refs"}
        }
        if summary and new_evidence != old_evidence:
            runtime["last_effective_progress"] = deps.clock().isoformat()
    if stage == "plan" and merged.plan:
        contract = merged.plan.contract.model_dump(mode="json")
        write_projection(deps, "harness/contract.json", contract)
        deps.lifecycle.emit("contract_ready", contract=contract)
        if state.plan is None or (
            merged.plan.root_cause_hypothesis != state.plan.root_cause_hypothesis
            or merged.plan.evidence != state.plan.evidence
        ):
            runtime["last_effective_progress"] = deps.clock().isoformat()
    for call in update.get("tool_calls", []):
        progress = call.get("result_summary", {}).get("exploration", {})
        if (
            progress.get("new_relevant_evidence")
            or progress.get("hypothesis_changed")
            or progress.get("candidate_changed")
        ):
            runtime["last_effective_progress"] = deps.clock().isoformat()
            runtime["progress_basis"] = "planned_file_overlap_or_stated_hypothesis; heuristic"
    runtime["event_seq"] = deps.events.last_seq + 1
    deps.lifecycle.emit("stage_end", duration_seconds=elapsed, runtime=runtime)
    return {
        **update,
        "runtime": runtime,
        "policy_snapshot": state.policy_snapshot,
        "experience_refs": state.experience_refs,
    }


def write_projection(deps: Deps, path: str, payload: Any) -> bool:
    try:
        deps.artifacts.write_json(path, payload)
        return True
    except Exception as exc:
        deps.lifecycle.emit("projection_error", artifact=path, error=str(exc))
        return False

