"""Offline, append-only improvement archives. No model, sandbox or network imports.

Only explicit selection changes future task advice. Historical results and costs
are never inputs to a write operation. Python code still uses worker/checkpoints.
"""

from __future__ import annotations

import argparse
import ast
import hashlib
import json
import os
import re
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_ARCHIVE = ROOT / "configs" / "harness"
SOURCE_FILES = (
    "agents/coder.py",
    "agents/planner.py",
    "agents/reviewer.py",
    "agents/exploration.py",
    "tools/query_cache.py",
    "tools/read_tools.py",
    "observability/resources.py",
    "observability/dispatch.py",
    "graph/validation_time.py",
    "tools/base.py",
    "llm/retry.py",
    "llm/dispatch_budget.py",
    "llm/openai_compatible.py",
    "llm/anthropic_messages.py",
    "storage/models.py",
    "storage/repository.py",
    "observability/runtime.py",
    "graph/deps.py",
    "graph/nodes.py",
    "graph/builder.py",
    "graph/checkpoint.py",
    "repo/index.py",
    "eval/assembly.py",
    "llm/tracking.py",
    "observability/lifecycle.py",
    "graph/evidence.py",
    "graph/harness.py",
    "tools/registry.py",
    "rsi.py",
)


def read_json(path: Path) -> dict[str, Any]:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise ValueError(f"expected JSON object: {path}")
    return payload


def version_dir(root: Path, version: str) -> Path:
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", version) or ".." in version:
        raise ValueError("invalid version identifier")
    path = root.resolve() / "candidates" / version
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("archive path escapes root")
    return path


def snapshot_sources() -> dict[str, str]:
    base = Path(__file__).resolve().parent
    return {name: (base / name).read_text(encoding="utf-8") for name in SOURCE_FILES}


def extract_prompts(sources: dict[str, str]) -> dict[str, str]:
    prompts = {}
    for role in ("coder", "planner", "reviewer"):
        for node in ast.walk(ast.parse(sources[f"agents/{role}.py"])):
            if not isinstance(node, ast.Assign):
                continue
            if any(
                (isinstance(t, ast.Name) and t.id == "_SYSTEM")
                or (isinstance(t, ast.Attribute) and t.attr == "system_prompt")
                for t in node.targets
            ):
                try:
                    value = ast.literal_eval(node.value)
                except ValueError:
                    continue
                if isinstance(value, str):
                    prompts[role] = value
                    break
    return prompts


def validate_snapshot(
    snapshot: dict[str, Any], root: Path | None = None, *, strict: bool = False
) -> dict[str, Any]:
    """Validate one policy snapshot.

    ``strict`` (Phase30) is the activation-grade check for newly generated
    candidates: all three role prompts must be present and non-empty. The
    default remains lenient so historical schema-1 fixtures keep loading; the
    strict gate is applied by the v4 generator (generation aborts) and by the
    harness fail-closed path (a selected candidate without prompts refuses to
    run instead of falling back to builtin defaults).
    """
    if snapshot.get("schema_version") != 1:
        raise ValueError("unsupported policy snapshot")
    if not isinstance(snapshot.get("instruction", ""), str):
        raise ValueError("instruction must be text")
    prompts = snapshot.get("prompts", {})
    if not isinstance(prompts, dict) or any(
        k not in {"coder", "planner", "reviewer"} or not isinstance(v, str)
        for k, v in prompts.items()
    ):
        raise ValueError("prompts must be versioned role text, not executable objects")
    if strict:
        missing_or_empty = sorted(
            role for role in ("coder", "planner", "reviewer") if not prompts.get(role)
        )
        if missing_or_empty:
            raise ValueError(
                "strict snapshot requires non-empty prompts for roles coder/planner/reviewer; "
                f"missing or empty: {missing_or_empty}"
            )
    entries = snapshot.get("experiences", [])
    if not isinstance(entries, list) or len(entries) > 100:
        raise ValueError("experiences must be a bounded list")
    required = {
        "id",
        "level",
        "source",
        "source_run",
        "applies_when",
        "invalid_when",
        "action",
        "version",
        "status",
        "evaluation_exposure",
    }
    for entry in entries:
        if not isinstance(entry, dict) or not required <= entry.keys():
            raise ValueError("experience provenance is incomplete")
        if entry["level"] not in {"L1", "L2", "L3"}:
            raise ValueError("L0 is task state; archived entries must be L1/L2/L3")
        if entry["evaluation_exposure"] != "public_only":
            raise ValueError("hidden-test/reference-patch experience is not injectable")
        if entry["level"] == "L3" and not entry.get("comparison_refs"):
            raise ValueError("L3 requires version comparison evidence")
        if entry["level"] == "L3":
            if root is None:
                raise ValueError("L3 comparison archive root required")
            for ref in entry["comparison_refs"]:
                if not isinstance(ref, str) or not re.fullmatch(r"[a-f0-9]{64}", ref):
                    raise ValueError("L3 comparison reference must be a content hash")
                comparison = read_json(root / "comparisons" / f"{ref}.json")
                if _json_hash(comparison) != ref:
                    raise ValueError("comparison identity mismatch")
                validate_comparison(root, comparison)
        if entry["status"] not in {"pending", "validated", "retired"}:
            raise ValueError("invalid experience status")
    return snapshot


def archive_root() -> Path:
    return Path(os.environ.get("CODEPILOT_HARNESS_ARCHIVE", str(DEFAULT_ARCHIVE))).resolve()


def load_selection(root: Path | None = None) -> dict[str, Any]:
    root = root if root is not None else archive_root()
    pointer = root / "active.json"
    if not pointer.exists():
        return {
            "schema_version": 1,
            "version": "builtin-phase26-v1",
            "parent": None,
            "status": "pending",
            "instruction": "",
            "experiences": [],
        }
    version = read_json(pointer)["version"]
    return validate_snapshot(read_json(version_dir(root, str(version)) / "snapshot.json"), root)


def selection_view(current: dict[str, Any]) -> dict[str, Any]:
    """Read-only configuration comparison; never applies the active pointer."""
    try:
        desired = load_selection()
        next_task = {"version": desired.get("version"), "status": desired.get("status", "pending")}
        return {
            "expected": next_task,
            "current_task": current,
            "next_task": next_task,
            "application": "new_tasks_only",
        }
    except (OSError, ValueError, KeyError) as exc:
        return {
            "current_task": current,
            "expected": None,
            "next_task": None,
            "application": "current_task_unchanged",
            "error": str(exc),
        }


def _condition(condition: Any, context: dict[str, Any]) -> bool | None:
    """Typed conjunction only. Unknown keys/values are not executable conditions."""
    if condition in (None, "", [], {}):
        return True
    if not isinstance(condition, dict):
        return None
    supported = {
        "repository",
        "stage",
        "failure_category",
        "runner",
        "environment",
        "version",
        "tags",
    }
    if not condition.keys() <= supported:
        return None
    for key, expected in condition.items():
        actual = context.get(key)
        if actual is None:
            return None
        if key == "tags":
            if not isinstance(expected, list) or not all(isinstance(v, str) for v in expected):
                return None
            if not set(expected) <= set(actual):
                return False
        elif isinstance(expected, str):
            if expected != "*" and actual != expected:
                return False
        elif isinstance(expected, list) and all(isinstance(v, str) for v in expected):
            if actual not in expected:
                return False
        else:
            return None
    return True


def retrieve(
    snapshot: dict[str, Any],
    repository: str,
    *,
    stage: str | None = None,
    failure_category: str | None = None,
    environment: dict[str, Any] | None = None,
    tags: tuple[str, ...] = (),
    audit: list[dict[str, Any]] | None = None,
    limit: int = 4,
    max_chars: int = 6000,
) -> list[dict[str, Any]]:
    """Rank advisory atomic entries; legacy prose is explicitly unevaluated."""
    context = {
        "repository": repository,
        "stage": stage,
        "failure_category": failure_category,
        "tags": tags,
        **(environment or {}),
    }
    decisions = audit if audit is not None else []
    eligible = []
    for entry in snapshot.get("experiences", []):
        reason = ""
        applicable = entry.get("applies_when")
        invalid = entry.get("invalid_when")
        invalid_match = _condition(invalid, context) if invalid else False
        legacy = isinstance(applicable, (str, list)) or isinstance(invalid, (str, list))
        if entry.get("status") == "retired":
            reason = "retired"
        elif entry.get("repository", "*") not in ("*", repository):
            reason = "repository_mismatch"
        elif entry.get("level") == "L1" and entry.get("repository", "*") == "*":
            reason = "L1_repository_required"
        elif invalid_match is True:
            reason = "invalid_when_matched"
        elif isinstance(invalid, dict) and invalid_match is None:
            reason = "invalid_when_unknown"
        elif isinstance(applicable, dict) and _condition(applicable, context) is not True:
            reason = "applies_when_unmet_or_unknown"
        if reason:
            decisions.append({"id": entry.get("id"), "decision": "rejected", "reason": reason})
            continue
        specificity = len(applicable) if isinstance(applicable, dict) else 0
        rank = (
            -specificity,
            entry.get("repository") != repository,
            entry.get("status") != "validated",
            not bool(entry.get("source_run")),
            str(entry.get("id", "")),
            str(entry.get("version", "")),
        )
        eligible.append(
            (
                rank,
                {
                    **entry,
                    "advisory": entry.get("status") != "validated" or legacy,
                    "conditions_evaluated": not legacy,
                    "condition_note": "legacy prose retained as explanation only"
                    if legacy
                    else "typed conditions",
                },
            )
        )
    chosen: list[dict[str, Any]] = []
    used = 0
    for _, entry in sorted(eligible, key=lambda pair: pair[0]):
        size = len(json.dumps(entry, ensure_ascii=False))
        reason = (
            "count_limit"
            if len(chosen) >= max(0, limit)
            else "context_limit"
            if used + size > max_chars
            else "matched"
        )
        decisions.append(
            {
                "id": entry["id"],
                "decision": "selected" if reason == "matched" else "truncated",
                "reason": reason,
            }
        )
        if reason == "matched":
            chosen.append(entry)
            used += size
    return chosen


def archive_candidate(_root: Path, _version: str, _proposal: dict[str, Any]) -> Path:
    """Retired (Phase29 I3): the schema-v1 archive path can no longer deliver.

    v1 ``candidate.json`` records carry no snapshot/diff integrity fields and no
    git source binding, so nothing written here could be verified. Every
    supported generation entry now goes through the single schema-v3 path in
    ``codepilot.archive.create_candidate`` (CLI: ``scripts/phase28_archive.py``).
    This stub keeps the name so stale call sites fail loudly instead of
    silently producing undeliverable v1 candidates.
    """
    raise ValueError(
        "rsi.archive_candidate is retired: schema v1 candidates are not "
        "deliverable. Use codepilot.archive.create_candidate (CLI: "
        "scripts/phase28_archive.py) to generate a schema-v3 candidate with "
        "source_commit binding and integrity verification"
    )


def select(root: Path, version: str, *, allow_pending: bool = False) -> None:
    snapshot = validate_snapshot(read_json(version_dir(root, version) / "snapshot.json"), root)
    if snapshot.get("status") != "validated" and not allow_pending:
        raise ValueError(
            "pending candidate: explicit --allow-pending required; effects remain unverified"
        )
    root.mkdir(parents=True, exist_ok=True)
    target = root / "active.json"
    temporary = root / "active.next.json"
    temporary.write_text(
        json.dumps({"version": version, "new_tasks_only": True}) + "\n", encoding="utf-8"
    )
    temporary.replace(target)


def replay(path: Path, *, decisions: bool = False) -> list[dict[str, Any]]:
    from codepilot.agents.exploration import exploration_feedback

    records = []
    with path.open(encoding="utf-8") as handle:
        for line_no, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                event = json.loads(line)
                if not isinstance(event, dict):
                    raise ValueError("event is not an object")
            except (ValueError, TypeError) as exc:
                records.append({"line": line_no, "error": str(exc)})
                continue
            if decisions:
                extra = event.get("extra")
                if not isinstance(extra, dict) or extra.get("hook") != "exploration":
                    continue
                facts = extra.get("facts")
                if not isinstance(facts, dict):
                    records.append({"line": line_no, "error": "exploration facts unavailable"})
                    continue
                records.append(
                    {
                        "line": line_no,
                        "mode": "deterministic_decision",
                        "old_feedback": facts.get("feedback"),
                        "feedback": exploration_feedback(facts),
                        "effect_validation": "NOT_RUN",
                    }
                )
            else:
                records.append({"line": line_no, "mode": "trace", "event": event})
    return records


def _json_hash(value: dict[str, Any]) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, ensure_ascii=False).encode()
    ).hexdigest()


def validate_comparison(root: Path, comparison: dict[str, Any]) -> None:
    """Validate imported evidence identity and comparability, never invent effects."""
    import math

    if (
        comparison.get("schema_version") != 1
        or comparison.get("evaluation_exposure") != "public_only"
    ):
        raise ValueError("comparison schema/public provenance required")
    if comparison.get("decision") not in {"accept", "reject", "observe"}:
        raise ValueError("explicit comparison decision required")
    if not comparison.get("reason") or not comparison.get("evidence_refs"):
        raise ValueError("comparison reason and original evidence references required")
    references = comparison["evidence_refs"]
    if not isinstance(references, list):
        raise ValueError("evidence_refs must contain hashed local evidence")
    for reference in references:
        if not isinstance(reference, dict) or set(reference) != {"path", "sha256"}:
            raise ValueError("each evidence reference requires path and sha256")
        evidence = (root / str(reference["path"])).resolve(strict=True)
        if not evidence.is_relative_to(root.resolve()) or not evidence.is_file():
            raise ValueError("comparison evidence escapes archive")
        if hashlib.sha256(evidence.read_bytes()).hexdigest() != reference["sha256"]:
            raise ValueError("comparison original evidence changed")
    sides = [comparison.get("baseline"), comparison.get("candidate")]
    required_conditions = {
        "model",
        "provider",
        "budget_hash",
        "environment_hash",
        "success_definition_hash",
        "task_set_hash",
    }
    for side in sides:
        if not isinstance(side, dict):
            raise ValueError("baseline and candidate records required")
        snapshot = read_json(version_dir(root, side["version"]) / "snapshot.json")
        if side.get("snapshot_hash") != _json_hash(snapshot):
            raise ValueError("comparison snapshot identity mismatch")
        conditions = side.get("conditions", {})
        if set(conditions) != required_conditions or not all(
            isinstance(v, str) and v for v in conditions.values()
        ):
            raise ValueError("frozen comparison conditions required")
        if any(
            not re.fullmatch(r"[a-f0-9]{64}", conditions[key])
            for key in required_conditions
            if key.endswith("_hash")
        ):
            raise ValueError("comparison condition hashes must be SHA256")
        runs = side.get("runs")
        if (
            not isinstance(runs, list)
            or not runs
            or not all(isinstance(run, str) and run for run in runs)
            or len(set(runs)) != len(runs)
        ):
            raise ValueError("unique original run IDs required")
        metrics = side.get("metrics", {})
        if set(metrics) != {"quality", "regressions", "seconds", "cost", "tool_calls"}:
            raise ValueError("independent quality/time/cost metrics required")
        if any(
            isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or v < 0
            for v in metrics.values()
        ):
            raise ValueError("finite nonnegative observed metrics required")
        if side.get("cost_known") is not True:
            raise ValueError("known cost and source runs required")
    baseline = comparison["baseline"]
    candidate = comparison["candidate"]
    if (
        baseline["version"] == candidate["version"]
        or baseline["conditions"] != candidate["conditions"]
    ):
        raise ValueError("distinct versions under identical frozen conditions required")


def import_comparison(root: Path, comparison: dict[str, Any]) -> str:
    validate_comparison(root, comparison)
    identity = _json_hash(comparison)
    folder = root / "comparisons"
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / f"{identity}.json"
    if not path.exists():
        with path.open("x", encoding="utf-8") as handle:
            handle.write(json.dumps(comparison, ensure_ascii=False, indent=2) + "\n")
    return identity


def promotion_readiness(root: Path, version: str, reference: str) -> dict[str, Any]:
    if not re.fullmatch(r"[a-f0-9]{64}", reference):
        raise ValueError("comparison hash required")
    comparison = read_json(root / "comparisons" / f"{reference}.json")
    if _json_hash(comparison) != reference:
        raise ValueError("comparison hash mismatch")
    validate_comparison(root, comparison)
    if comparison["candidate"]["version"] != version:
        raise ValueError("comparison belongs to another candidate")
    quality_floor = (
        comparison["candidate"]["metrics"]["quality"]
        >= comparison["baseline"]["metrics"]["quality"]
        and comparison["candidate"]["metrics"]["regressions"]
        <= comparison["baseline"]["metrics"]["regressions"]
    )
    return {
        "version": version,
        "comparison": reference,
        "eligible_for_manual_review": comparison["decision"] == "accept" and quality_floor,
        "quality_floor_met": quality_floor,
        "status": "pending",
        "auto_promote": False,
        "next_action": "Review original evidence and independent coverage before explicitly selecting; no source checkout is changed.",
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=DEFAULT_ARCHIVE)
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("list")
    comparison_parser = sub.add_parser("import-comparison")
    comparison_parser.add_argument("path", type=Path)
    promotion = sub.add_parser("promotion-readiness")
    promotion.add_argument("version")
    promotion.add_argument("reference")
    for command in ("show", "select", "rollback"):
        item = sub.add_parser(command)
        item.add_argument("version")
        if command != "show":
            item.add_argument("--allow-pending", action="store_true")
    trace = sub.add_parser("replay")
    trace.add_argument("path", type=Path)
    trace.add_argument("--mode", choices=("trace", "decision"), default="trace")
    args = parser.parse_args()
    if args.command == "list":
        result: Any = [
            p.parent.name for p in sorted((args.root / "candidates").glob("*/snapshot.json"))
        ]
    elif args.command == "import-comparison":
        result = import_comparison(args.root, read_json(args.path))
    elif args.command == "promotion-readiness":
        result = promotion_readiness(args.root, args.version, args.reference)
    elif args.command == "replay":
        result = replay(args.path, decisions=args.mode == "decision")
    elif args.command == "show":
        result = read_json(version_dir(args.root, args.version) / "candidate.json")
    else:
        version = args.version
        if args.command == "rollback":
            version = read_json(version_dir(args.root, version) / "snapshot.json").get("parent")
            if not version:
                raise ValueError("candidate has no archived parent")
        select(args.root, version, allow_pending=args.allow_pending)
        result = {"selected_for_new_tasks": version, "historical_results_unchanged": True}
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

src/codepilot/storage/repository.py:
"""数据访问层（02 §18.1）。

设计约定：

- 每个 store 在构造时接收一个 ``Session``，自己**不创建** session，也不提交。
  事务边界由调用方（``session_scope``）决定，否则一个失败的回滚会顺手把
  别的模块已经写好的数据一起丢掉。
- 索引类写入用"先删后插"而不是逐行 upsert：增量索引的语义本来就是
  "删除并重建与这些文件相关的边"（02 §7.7），而且批量插入比逐行 merge
  快一到两个数量级——一个中型仓库有几万个 symbol。
- 查询返回 ORM 行对象。需要领域对象时由上层转换，这一层不做业务判断。
"""

from __future__ import annotations

from collections.abc import Iterable, Sequence
from datetime import datetime
from typing import Any, cast

from sqlalchemy import CursorResult, delete, func, insert, select
from sqlalchemy.orm import Session

from codepilot.clock import utcnow
from codepilot.storage.models import (
    Attempt,
    Evaluation,
    Event,
    FileNode,
    GraphEdge,
    IndexSemantics,
    RepositoryRow,
    Run,
    SymbolRow,
    Task,
)

__all__ = [
    "AttemptStore",
    "EdgeStore",
    "EvaluationStore",
    "EventStore",
    "FileStore",
    "RepositoryStore",
    "RunStore",
    "Stores",
    "SymbolStore",
    "TaskStore",
]


class RepositoryStore:
    """``repositories`` 表。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def upsert(
        self,
        *,
        repository_id: str,
        url: str,
        base_commit: str,
        indexed_at: datetime | None = None,
    ) -> RepositoryRow:
        row = self._s.get(RepositoryRow, repository_id)
        if row is None:
            row = RepositoryRow(
                id=repository_id, url=url, base_commit=base_commit, indexed_at=indexed_at
            )
            self._s.add(row)
        else:
            row.url = url
            row.base_commit = base_commit
            if indexed_at is not None:
                row.indexed_at = indexed_at
        self._s.flush()
        return row

    def get(self, repository_id: str) -> RepositoryRow | None:
        return self._s.get(RepositoryRow, repository_id)

    def index_semantics(self, repository_id: str) -> str | None:
        row = self._s.get(IndexSemantics, repository_id)
        return row.fingerprint if row is not None else None

    def set_index_semantics(self, repository_id: str, fingerprint: str) -> None:
        self._s.merge(IndexSemantics(repository_id=repository_id, fingerprint=fingerprint))
        self._s.flush()

    def find_by_url_commit(self, url: str, base_commit: str) -> RepositoryRow | None:
        stmt = select(RepositoryRow).where(
            RepositoryRow.url == url, RepositoryRow.base_commit == base_commit
        )
        return self._s.execute(stmt).scalar_one_or_none()

    def mark_indexed(self, repository_id: str, when: datetime | None = None) -> None:
        row = self._s.get(RepositoryRow, repository_id)
        if row is None:
            raise KeyError(f"repository not found: {repository_id}")
        row.indexed_at = when or utcnow()


class FileStore:
    """``files`` 表。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def upsert_many(self, rows: Iterable[dict[str, object]]) -> None:
        """按主键 upsert。

        文件数量远小于 symbol 数量，逐行处理是可以接受的，而且能保留
        ``parse_error`` 这类"本次没解析但上次有值"的字段语义。
        """
        for data in rows:
            file_id = str(data["id"])
            row = self._s.get(FileNode, file_id)
            if row is None:
                self._s.add(FileNode(**data))
            else:
                for key, value in data.items():
                    setattr(row, key, value)
        self._s.flush()

    def get(self, file_id: str) -> FileNode | None:
        return self._s.get(FileNode, file_id)

    def get_by_path(self, repository_id: str, path: str) -> FileNode | None:
        stmt = select(FileNode).where(
            FileNode.repository_id == repository_id, FileNode.path == path
        )
        return self._s.execute(stmt).scalar_one_or_none()

    def list_by_repo(self, repository_id: str) -> list[FileNode]:
        stmt = (
            select(FileNode).where(FileNode.repository_id == repository_id).order_by(FileNode.path)
        )
        return list(self._s.execute(stmt).scalars())

    def delete_by_paths(self, repository_id: str, paths: Sequence[str]) -> list[str]:
        """删除文件并返回被删的 file id（调用方据此清理 symbol 与边）。"""
        if not paths:
            return []
        stmt = select(FileNode.id).where(
            FileNode.repository_id == repository_id, FileNode.path.in_(paths)
        )
        ids = list(self._s.execute(stmt).scalars())
        if ids:
            self._s.execute(delete(FileNode).where(FileNode.id.in_(ids)))
        return ids


class SymbolStore:
    """``symbols`` 表。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def replace_for_files(self, file_ids: Sequence[str], rows: Iterable[dict[str, object]]) -> None:
        """删除这些文件的全部 symbol，再插入新的。

        增量索引只重建受影响文件的 symbol；未被重新解析的文件其 symbol 保持原样。
        """
        if file_ids:
            self._s.execute(delete(SymbolRow).where(SymbolRow.file_id.in_(file_ids)))
        materialized = list(rows)
        if materialized:
            self._s.execute(insert(SymbolRow), materialized)
        self._s.flush()

    def get(self, symbol_id: str) -> SymbolRow | None:
        return self._s.get(SymbolRow, symbol_id)

    def get_by_qualified_name(self, repository_id: str, qualified_name: str) -> list[SymbolRow]:
        """返回列表而不是单值：同名重复定义是合法的（02 §7.2 规则）。"""
        stmt = select(SymbolRow).where(
            SymbolRow.repository_id == repository_id,
            SymbolRow.qualified_name == qualified_name,
        )
        return list(self._s.execute(stmt).scalars())

    def find_by_name(self, repository_id: str, name: str, limit: int = 50) -> list[SymbolRow]:
        """按裸名模糊匹配，供 ``find_symbol`` 工具使用。"""
        stmt = (
            select(SymbolRow)
            .where(
                SymbolRow.repository_id == repository_id,
                SymbolRow.name.ilike(f"%{name}%"),
            )
            .order_by(func.length(SymbolRow.qualified_name))
            .limit(limit)
        )
        return list(self._s.execute(stmt).scalars())

    def list_by_repo(self, repository_id: str) -> list[SymbolRow]:
        stmt = select(SymbolRow).where(SymbolRow.repository_id == repository_id)
        return list(self._s.execute(stmt).scalars())

    def list_by_file(self, file_id: str) -> list[SymbolRow]:
        stmt = select(SymbolRow).where(SymbolRow.file_id == file_id).order_by(SymbolRow.start_line)
        return list(self._s.execute(stmt).scalars())

    def list_ids_for_files(self, file_ids: Sequence[str]) -> list[str]:
        """一批文件的全部 symbol id。增量索引在删除前取出，用于清理相关的边。"""
        if not file_ids:
            return []
        stmt = select(SymbolRow.id).where(SymbolRow.file_id.in_(file_ids))
        return list(self._s.execute(stmt).scalars())

    def count_by_kind(self, repository_id: str) -> dict[str, int]:
        stmt = (
            select(SymbolRow.kind, func.count())
            .where(SymbolRow.repository_id == repository_id)
            .group_by(SymbolRow.kind)
        )
        # 不能用 dict(result)：SQLAlchemy 的 Result 迭代出的是 Row 对象，
        # 它满足序列协议但不满足 mapping 协议，dict() 会直接抛 TypeError。
        return {kind: count for kind, count in self._s.execute(stmt)}  # noqa: C416


class EdgeStore:
    """``edges`` 表。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def replace_for_sources(
        self, repository_id: str, source_ids: Sequence[str], rows: Iterable[dict[str, object]]
    ) -> None:
        if source_ids:
            self._s.execute(
                delete(GraphEdge).where(
                    GraphEdge.repository_id == repository_id,
                    GraphEdge.source_id.in_(source_ids),
                )
            )
        from itertools import batched

        for batch in batched(rows, 1000):
            self._s.execute(insert(GraphEdge), list(batch))
        self._s.flush()

    def list_by_repo(self, repository_id: str) -> list[GraphEdge]:
        stmt = select(GraphEdge).where(GraphEdge.repository_id == repository_id)
        return list(self._s.execute(stmt).scalars())

    def out_edges(self, source_id: str) -> list[GraphEdge]:
        """调用者 / 子类 / import 的出发边。"""
        stmt = select(GraphEdge).where(GraphEdge.source_id == source_id)
        return list(self._s.execute(stmt).scalars())

    def in_edges(self, target_id: str) -> list[GraphEdge]:
        """谁调用了它。``target_id`` 为空（未解析到目标）的边不会出现在这里。"""
        stmt = select(GraphEdge).where(GraphEdge.target_id == target_id)
        return list(self._s.execute(stmt).scalars())

    def in_edges_by_name(self, repository_id: str, target_name: str) -> list[GraphEdge]:
        """按名字找调用方。用于目标未解析但名字已知的情形。"""
        stmt = select(GraphEdge).where(
            GraphEdge.repository_id == repository_id,
            GraphEdge.target_name == target_name,
        )
        return list(self._s.execute(stmt).scalars())

    def count_by_kind_confidence(self, repository_id: str) -> dict[tuple[str, float], int]:
        """按 (kind, confidence) 分组计数。``codepilot index`` 的输出与
        Phase 1 golden test 都依赖它。"""
        stmt = (
            select(GraphEdge.kind, GraphEdge.confidence, func.count())
            .where(GraphEdge.repository_id == repository_id)
            .group_by(GraphEdge.kind, GraphEdge.confidence)
        )
        return {(kind, conf): count for kind, conf, count in self._s.execute(stmt)}

    def get(self, edge_id: str) -> GraphEdge | None:
        return self._s.get(GraphEdge, edge_id)

    def delete_by_ids(self, repository_id: str, edge_ids: Sequence[str]) -> int:
        if not edge_ids:
            return 0
        # DML 的 execute 运行时返回 CursorResult（带 rowcount），但桩把 Session.execute
        # 声明为 Result；cast 补上这个已知的类型缺口，不改变运行时行为。
        result = cast(
            "CursorResult[Any]",
            self._s.execute(
                delete(GraphEdge).where(
                    GraphEdge.repository_id == repository_id,
                    GraphEdge.id.in_(edge_ids),
                )
            ),
        )
        self._s.flush()
        return result.rowcount or 0

    def delete_by_kind(self, repository_id: str, kind: str) -> int:
        """删除某仓库下指定种类的全部边。索引层用它整体替换 TEST 边集合。"""
        result = cast(
            "CursorResult[Any]",
            self._s.execute(
                delete(GraphEdge).where(
                    GraphEdge.repository_id == repository_id,
                    GraphEdge.kind == kind,
                )
            ),
        )
        self._s.flush()
        return result.rowcount or 0

    def list_dangling_targets(self, repository_id: str) -> list[GraphEdge]:
        """``target_id`` 指向已不存在 symbol 的边（增量重建后由索引层处理）。"""
        valid = select(SymbolRow.id).where(SymbolRow.repository_id == repository_id)
        stmt = select(GraphEdge).where(
            GraphEdge.repository_id == repository_id,
            GraphEdge.target_id.is_not(None),
            GraphEdge.target_id.notin_(valid),
        )
        return list(self._s.execute(stmt).scalars())


class TaskStore:
    """``tasks`` 表。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def upsert(
        self,
        *,
        task_id: str,
        repository_id: str,
        issue: str,
        mode: str,
        config_hash: str = "",
    ) -> Task:
        row = self._s.get(Task, task_id)
        if row is None:
            row = Task(
                id=task_id,
                repository_id=repository_id,
                issue=issue,
                mode=mode,
                config_hash=config_hash,
                created_at=utcnow(),
            )
            self._s.add(row)
        else:
            row.issue = issue
            row.config_hash = config_hash
        self._s.flush()
        return row

    def get(self, task_id: str) -> Task | None:
        return self._s.get(Task, task_id)

    def list_by_repo(self, repository_id: str) -> list[Task]:
        stmt = select(Task).where(Task.repository_id == repository_id)
        return list(self._s.execute(stmt).scalars())


class RunStore:
    """``runs`` 表。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def create(
        self,
        *,
        run_id: str,
        task_id: str,
        code_version: str = "",
        started_at: datetime | None = None,
    ) -> Run:
        row = Run(
            id=run_id,
            task_id=task_id,
            status="running",
            code_version=code_version,
            started_at=started_at or utcnow(),
        )
        self._s.add(row)
        self._s.flush()
        return row

    def get(self, run_id: str) -> Run | None:
        return self._s.get(Run, run_id)

    def finish(
        self,
        run_id: str,
        *,
        status: str,
        stop_reason: str | None,
        usage: dict[str, object],
        finished_at: datetime | None = None,
    ) -> None:
        row = self._s.get(Run, run_id)
        if row is None:
            raise KeyError(f"run not found: {run_id}")
        row.status = status
        row.stop_reason = stop_reason
        row.usage = dict(usage)
        row.finished_at = finished_at or utcnow()

    def list_by_task(self, task_id: str) -> list[Run]:
        stmt = select(Run).where(Run.task_id == task_id).order_by(Run.started_at)
        return list(self._s.execute(stmt).scalars())


class AttemptStore:
    """``attempts`` 表。``(run_id, iteration)`` 唯一。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def upsert(
        self,
        *,
        run_id: str,
        iteration: int,
        patch_hash: str = "",
        status: str = "",
        artifact_dir: str = "",
    ) -> None:
        stmt = select(Attempt).where(Attempt.run_id == run_id, Attempt.iteration == iteration)
        row = self._s.execute(stmt).scalar_one_or_none()
        if row is None:
            self._s.add(
                Attempt(
                    run_id=run_id,
                    iteration=iteration,
                    patch_hash=patch_hash,
                    status=status,
                    artifact_dir=artifact_dir,
                )
            )
        else:
            row.patch_hash = patch_hash
            row.status = status
            row.artifact_dir = artifact_dir
        self._s.flush()

    def list_by_run(self, run_id: str) -> list[Attempt]:
        stmt = select(Attempt).where(Attempt.run_id == run_id).order_by(Attempt.iteration)
        return list(self._s.execute(stmt).scalars())


class EventStore:
    """``events`` 表。``seq`` 由本类分配，保证每 run 内连续且单调。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def next_seq(self, run_id: str) -> int:
        stmt = select(func.max(Event.seq)).where(Event.run_id == run_id)
        current = self._s.execute(stmt).scalar()
        return (current or 0) + 1

    def append(
        self,
        *,
        run_id: str,
        node: str,
        type: str,
        payload: dict[str, object] | None = None,
        seq: int | None = None,
        timestamp: datetime | None = None,
    ) -> Event:
        row = Event(
            run_id=run_id,
            seq=seq if seq is not None else self.next_seq(run_id),
            node=node,
            type=type,
            payload=dict(payload or {}),
            timestamp=timestamp or utcnow(),
        )
        self._s.add(row)
        self._s.flush()
        return row

    def list_after(self, run_id: str, after_seq: int = 0) -> list[Event]:
        """SSE 断线续传用（02 §19：``?after_seq=``）。"""
        stmt = (
            select(Event).where(Event.run_id == run_id, Event.seq > after_seq).order_by(Event.seq)
        )
        return list(self._s.execute(stmt).scalars())


class EvaluationStore:
    """``evaluations`` 表。``(run_id, benchmark)`` 唯一。"""

    def __init__(self, session: Session) -> None:
        self._s = session

    def upsert(
        self,
        *,
        run_id: str,
        benchmark: str,
        resolved: bool,
        metrics: dict[str, object] | None = None,
    ) -> None:
        stmt = select(Evaluation).where(
            Evaluation.run_id == run_id, Evaluation.benchmark == benchmark
        )
        row = self._s.execute(stmt).scalar_one_or_none()
        if row is None:
            self._s.add(
                Evaluation(
                    run_id=run_id,
                    benchmark=benchmark,
                    resolved=resolved,
                    metrics=dict(metrics or {}),
                )
            )
        else:
            row.resolved = resolved
            row.metrics = dict(metrics or {})
        self._s.flush()

    def list_by_run(self, run_id: str) -> list[Evaluation]:
        stmt = select(Evaluation).where(Evaluation.run_id == run_id)
        return list(self._s.execute(stmt).scalars())

    def list_by_benchmark(self, benchmark: str) -> list[Evaluation]:
        stmt = select(Evaluation).where(Evaluation.benchmark == benchmark)
        return list(self._s.execute(stmt).scalars())


class Stores:
    """把各 store 挂在同一个 session 上，供调用方一次性构造。

    ``with session_scope(factory) as session: stores = Stores(session)``

    不用 ``@dataclass``：九个 store 都是构造时创建的，写成 dataclass 字段会
    让它们变成必填参数，必须由调用方逐个传入，反而更啰嗦。
    """

    def __init__(self, session: Session) -> None:
        self.session = session
        self.repositories = RepositoryStore(session)
        self.files = FileStore(session)
        self.symbols = SymbolStore(session)
        self.edges = EdgeStore(session)
        self.tasks = TaskStore(session)
        self.runs = RunStore(session)
        self.attempts = AttemptStore(session)
        self.events = EventStore(session)
        self.evaluations = EvaluationStore(session)

src/codepilot/tools/base.py:
"""工具公共契约与唯一的 workspace 路径安全实现（P-06）。"""

from __future__ import annotations

from collections.abc import Callable, Iterable
from enum import StrEnum
from pathlib import Path, PurePosixPath, PureWindowsPath
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, ValidationError

from codepilot.llm.types import ToolSpec
from codepilot.schemas.reproduction import REPRO_TEST_DIRECTORY

__all__ = [
    "PathAccessError",
    "Tool",
    "ToolError",
    "ToolPermission",
    "ToolResponse",
    "WorkspacePathPolicy",
]

_REPRODUCTION_PARTS = tuple(REPRO_TEST_DIRECTORY.split("/"))
_REPRODUCTION_DIRECTORY_NAME = _REPRODUCTION_PARTS[-1]
_REPRODUCTION_FORBIDDEN_NAMES = frozenset(
    {
        "conftest.py",
        "pytest.ini",
        "tox.ini",
        "setup.cfg",
        "pyproject.toml",
        "__init__.py",
    }
)


def _touches_reproduction_directory(path: PurePosixPath) -> bool:
    """大小写不敏感地判断路径是否落在复现目录里（Windows 上大小写不敏感）。"""
    directories = tuple(item.casefold() for item in path.parts[:-1])
    return (
        _REPRODUCTION_DIRECTORY_NAME.casefold() in directories
        or tuple(item.casefold() for item in path.parts[:2]) == _REPRODUCTION_PARTS
    )


class ToolPermission(StrEnum):
    READ = "read"
    WRITE = "write"
    EXECUTE = "execute"


class ToolError(BaseModel):
    code: str
    message: str
    details: dict[str, Any] = Field(default_factory=dict)


class ToolResponse(BaseModel):
    ok: bool
    tool: str
    data: dict[str, Any] = Field(default_factory=dict)
    error: ToolError | None = None

    @classmethod
    def success(cls, tool: str, **data: Any) -> ToolResponse:
        return cls(ok=True, tool=tool, data=data)

    @classmethod
    def failure(cls, tool: str, code: str, message: str, **details: Any) -> ToolResponse:
        return cls(
            ok=False,
            tool=tool,
            error=ToolError(code=code, message=message, details=details),
        )


class PathAccessError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


class WorkspacePathPolicy:
    """Realpath-based boundary check shared by every file-facing tool.

    ``deny_directories`` is an explicit, auditable configuration. No fuzzy name
    matching is used, so ordinary fixtures and public tests are not blocked.

    ``repro_write`` is the single, minimal exception for the reproduction test
    directory (Phase 6 D-05). It is a **trusted construction parameter**: no
    model-facing argument can set it, so a Coding Agent cannot widen its own
    permissions by naming a path under ``tests/_codepilot_repro/``.
    """

    DEFAULT_DENY_DIRECTORIES = frozenset(
        {".git", ".codepilot", "private-eval", "hidden-answers", "artifacts/runs"}
    )
    DEFAULT_DENY_FILES: frozenset[str] = frozenset()

    def __init__(
        self,
        workspace: Path,
        *,
        deny_directories: Iterable[str] = DEFAULT_DENY_DIRECTORIES,
        deny_files: Iterable[str] = DEFAULT_DENY_FILES,
        repro_write: bool = False,
        allow_new_tests: bool = False,
        deny_existing_test_edits: bool = False,
    ) -> None:
        root = Path(workspace).resolve(strict=True)
        if not root.is_dir():
            raise ValueError("workspace must be an existing directory")
        self.root = root
        self.deny_directories = frozenset(self._normalize_rule(item) for item in deny_directories)
        self.deny_files = frozenset(self._normalize_rule(item) for item in deny_files)
        self.repro_write = bool(repro_write)
        self.allow_new_tests = bool(allow_new_tests)
        self.deny_existing_test_edits = bool(deny_existing_test_edits)

    @staticmethod
    def _normalize_rule(value: str) -> str:
        return value.strip("/\\").replace("\\", "/")

    def resolve(
        self,
        relative: str,
        *,
        must_exist: bool,
        expect_file: bool = True,
        for_write: bool = False,
    ) -> Path:
        if not isinstance(relative, str) or not relative.strip():
            raise PathAccessError("invalid_path", "path must be a non-empty string")
        windows = PureWindowsPath(relative)
        normalized = relative.replace("\\", "/")
        posix = PurePosixPath(normalized)
        if (
            windows.is_absolute()
            or bool(windows.anchor)
            or posix.is_absolute()
            or ".." in posix.parts
        ):
            raise PathAccessError("path_escape", "absolute, UNC and parent paths are forbidden")
        lexical = Path(*posix.parts)
        self._check_denylist(posix)
        self._check_reproduction_directory(posix, for_write=for_write)

        if (
            for_write
            and not must_exist
            and not self.allow_new_tests
            and not (self.repro_write and _touches_reproduction_directory(posix))
            and is_test_path(posix.as_posix())
        ):
            raise PathAccessError("forbidden_path", "new tests require trusted task authorization")

        candidate = self.root / lexical
        try:
            resolved = candidate.resolve(strict=must_exist)
        except FileNotFoundError as exc:
            raise PathAccessError("not_found", f"path does not exist: {normalized}") from exc
        if not resolved.is_relative_to(self.root):
            raise PathAccessError("path_escape", "resolved path escapes the workspace")

        # A missing leaf may still have a symlink parent; resolve(strict=False) above
        # follows it. Recheck the existing parent identity immediately before use.
        parent_candidate = self.root if candidate == self.root else candidate.parent
        while not parent_candidate.exists() and parent_candidate != self.root:
            parent_candidate = parent_candidate.parent
        parent = parent_candidate.resolve(strict=True)
        if not parent.is_relative_to(self.root):
            raise PathAccessError("path_escape", "resolved parent escapes the workspace")
        if (
            for_write
            and not must_exist
            and not self.allow_new_tests
            and is_test_path(resolved.relative_to(self.root).as_posix())
            and not (self.repro_write and _touches_reproduction_directory(posix))
        ):
            raise PathAccessError(
                "forbidden_path", "resolved new test requires trusted task authorization"
            )
        if (
            for_write
            and must_exist
            and self.deny_existing_test_edits
            and is_test_path(resolved.relative_to(self.root).as_posix())
            and not (self.repro_write and _touches_reproduction_directory(posix))
        ):
            raise PathAccessError(
                "forbidden_path",
                f"existing test is read-only: {normalized}; edit production source instead",
            )
        if for_write:
            self._check_reproduction_parent(posix, resolved, for_write=for_write)
        if must_exist and expect_file and not resolved.is_file():
            raise PathAccessError("not_file", f"path is not a file: {normalized}")
        if not must_exist and candidate.exists():
            raise PathAccessError("already_exists", f"path already exists: {normalized}")
        return resolved

    def resolve_directory(self, relative: str) -> Path:
        resolved = self.resolve(relative, must_exist=True, expect_file=False)
        if not resolved.is_dir():
            raise PathAccessError("not_directory", "search prefix is not a directory")
        lexical = self.root / relative
        for part in (lexical, *lexical.parents):
            if part == self.root:
                break
            if part.is_symlink():
                raise PathAccessError(
                    "symlink_directory", "search never follows directory symlinks"
                )
        self._check_denylist(PurePosixPath(resolved.relative_to(self.root).as_posix()))
        return resolved

    def check_historical_read(self, relative: str) -> Path:
        """Authorize a historical source path regardless of current existence.

        Creation semantics of resolve(must_exist=False) remain unchanged. Both
        lexical and resolved scopes are checked, including missing symlink leaves.
        """
        candidate = self.root / relative
        resolved = self.resolve(relative, must_exist=candidate.exists())
        self._check_denylist(PurePosixPath(resolved.relative_to(self.root).as_posix()))
        return resolved

    def relative(self, path: Path) -> str:
        resolved = path.resolve(strict=True)
        if not resolved.is_relative_to(self.root):
            raise PathAccessError("path_escape", "path escapes workspace")
        return resolved.relative_to(self.root).as_posix()

    def _check_denylist(self, path: PurePosixPath) -> None:
        text = path.as_posix()
        prefixes = [
            PurePosixPath(*path.parts[:index]).as_posix() for index in range(1, len(path.parts) + 1)
        ]
        if any(prefix in self.deny_directories for prefix in prefixes):
            raise PathAccessError("forbidden_path", f"path is denied by policy: {text}")
        if text in self.deny_files:
            raise PathAccessError("forbidden_path", f"file is denied by policy: {text}")

    def _check_reproduction_directory(self, path: PurePosixPath, *, for_write: bool) -> None:
        """复现目录的写入例外：无凭证一律拒绝，有凭证也只允许规范位置。

        读取不受影响——ReproductionAgent 与 Sandbox 都要能读到复现测试（D-07）。
        """
        if not for_write or not _touches_reproduction_directory(path):
            return
        if not self.repro_write:
            raise PathAccessError(
                "forbidden_path",
                "the reproduction test directory requires a trusted reproduction context",
            )
        parts = path.parts
        if parts[:2] != _REPRODUCTION_PARTS or len(parts) != 3:
            raise PathAccessError(
                "forbidden_path",
                f"reproduction files must live exactly at {REPRO_TEST_DIRECTORY}/<test_*.py>",
            )
        leaf = parts[-1]
        if leaf.casefold() in _REPRODUCTION_FORBIDDEN_NAMES:
            raise PathAccessError("forbidden_path", f"protected configuration file: {leaf}")
        if not leaf.startswith("test_") or not leaf.endswith(".py") or "/" in leaf:
            raise PathAccessError("forbidden_path", f"not a reproduction test file: {leaf}")

    def _check_reproduction_parent(
        self, path: PurePosixPath, resolved: Path, *, for_write: bool
    ) -> None:
        """目录必须是真的在那棵树里，不是被 symlink 换出来的（D-05 第 6 条）。"""
        if not for_write or not self.repro_write or not _touches_reproduction_directory(path):
            return
        if resolved.parent != self.root.joinpath(*_REPRODUCTION_PARTS):
            raise PathAccessError(
                "path_escape", "reproduction directory is not the workspace's own directory"
            )

    def verify_identity(self, path: Path) -> None:
        """Detect a path replacement between validation and the actual operation."""
        resolved = path.resolve(strict=True)
        if not resolved.is_relative_to(self.root) or not path.samefile(resolved):
            raise PathAccessError("identity_changed", "target identity changed after validation")


ToolHandler = Callable[[BaseModel], ToolResponse]


class Tool:
    """A uniquely named, schema-described callable tool."""

    def __init__(
        self,
        *,
        name: str,
        description: str,
        permission: ToolPermission,
        input_model: type[BaseModel],
        handler: ToolHandler,
    ) -> None:
        self.name = name
        self.description = description
        self.permission = permission
        self.input_model = input_model
        self._handler = handler

    def spec(self) -> ToolSpec:
        return ToolSpec(
            name=self.name,
            description=self.description,
            parameters=self.input_model.model_json_schema(),
        )

    def execute(self, arguments: dict[str, Any]) -> ToolResponse:
        try:
            parsed = self.input_model.model_validate(arguments)
        except ValidationError as exc:
            return ToolResponse.failure(
                self.name,
                "invalid_arguments",
                "tool arguments failed schema validation",
                validation_errors=exc.errors(include_url=False),
            )
        try:
            return self._handler(parsed)
        except PathAccessError as exc:
            return ToolResponse.failure(self.name, exc.code, str(exc))
        except (OSError, ValueError) as exc:
            return ToolResponse.failure(self.name, "tool_error", str(exc))


class EmptyInput(BaseModel):
    model_config = ConfigDict(extra="forbid")


def is_test_path(relative: str) -> bool:
    path = PurePosixPath(relative.replace("\\", "/").casefold())
    return "tests" in path.parts or path.name.startswith("test_") or path.name.endswith("_test.py")

